DO $blk$
DECLARE uid uuid := gen_random_uuid();
BEGIN
  -- GUARDA: solo en una base SIN empleados, o sea un branch recién creado.
  -- En producción hay 50, así que esto no se ejecuta jamás ahí. Es lo único
  -- que separa "sembrar el entorno de pruebas" de "crear una cuenta con rol
  -- de Gerente General en la base real".
  IF EXISTS (SELECT 1 FROM public.employees) THEN RETURN; END IF;

  -- Las columnas de token van en cadena vacía, NO en NULL: GoTrue las lee como
  -- texto no nulo y con NULL el login falla con "Database error querying schema",
  -- que no menciona ni la columna ni la tabla.
  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, created_at, updated_at,
    raw_app_meta_data, raw_user_meta_data,
    confirmation_token, recovery_token, email_change, email_change_token_new,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) VALUES (
    '00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated',
    'pruebas@farmalasa.app',
    extensions.crypt('pruebas2026', extensions.gen_salt('bf')),
    now(), now(), now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('code', '9001'),
    '', '', '', '', '', '', '', ''
  );

